steps.script:
var ov = tree.root.get_node_or_null("/root/TutorialOverlay")
var q = [ov]
while not q.is_empty():
	var n = q.pop_front()
	if n is RichTextLabel and n.name == "BodyText" and n.is_visible_in_tree():
		return "✚" in str(n.text)
	for c in n.get_children():
		q.append(c)
return "no body text"

var ov = tree.root.get_node_or_null("/root/TutorialOverlay")
var q = [ov]
while not q.is_empty():
	var n = q.pop_front()
	if n is RichTextLabel and n.name == "BodyText" and n.is_visible_in_tree():
		return "LS" in str(n.text)
	for c in n.get_children():
		q.append(c)
return "no body text"

var lst = tree.root.get_node_or_null("/root/Main/HUD_Right/VBoxContainer/FightScrollContainer/FightPanel/FightSelectionPanel/UnitList")
var enemy = lst.get_node_or_null("Fight_U_CUSTODIAN_GUARD_T")
var f = tree.root.get_viewport().gui_get_focus_owner()
return "%s|%s" % [enemy != null and enemy.disabled, f != null and f.name == "Fight_U_CUSTODIAN_GUARD_T"]

for c in tree.root.get_children():
	if c is AcceptDialog and c.visible and str(c.title).begins_with("Epic Challenge"):
		for btn in c.find_children("*", "Button", true, false):
			if btn.text == "Decline":
				btn.pressed.emit()
				return "declined"
return "no epic dialog"

var fast = tree.root.get_node_or_null("/root/Main/HUD_Right/VBoxContainer/FightScrollContainer/FightPanel/FightResolutionDock/DockFastButton")
if fast != null and fast.is_visible_in_tree() and not fast.disabled:
	fast.pressed.emit()
	return true
return false

var u = GameState.state.get("units", {})
var ph = PhaseManager.get_current_phase_instance()
return "%s|%s|%s" % [
	u.get("U_BOYZ_T", {}).get("flags", {}).get("has_fought", false),
	u.get("U_WARBOSS_T", {}).get("flags", {}).get("has_fought", false),
	str(ph.sequencer_11e.eligible_units(GameState.state, 1, false))]

var ov = tree.root.get_node_or_null("/root/TutorialOverlay")
var q = [ov]
while not q.is_empty():
	var n = q.pop_front()
	if n is RichTextLabel and n.name == "BodyText" and n.is_visible_in_tree():
		return "LS" in str(n.text)
	for c in n.get_children():
		q.append(c)
return "no body text"

var f = tree.root.get_viewport().gui_get_focus_owner()
if f == null:
	return "no focus"
var ov = tree.root.get_node_or_null("/root/Main/AllocationGroupOverlay")
if ov == null or not ov.is_ancestor_of(f):
	return "focus outside card: " + str(f.get_path())
return "Roll Saves" in str(f.text)
